<?php if($view==='wishlist'): $list=rows('SELECT p.* FROM products p JOIN wishlist_items w ON w.product_id=p.id WHERE w.cart_id=? AND p.status="publish"',[cart_id()]); ?>
<div class="shop-area py-90"><div class="container"><div class="row store-grid"><?php foreach($list as $p): ?><div class="col-6 col-md-4 col-lg-3"><div class="product-item"><div class="product-img"><img loading="lazy" src="<?= h(url($p['image']?:'assets/img/logo/favicon.png')) ?>" alt="<?= h($p['name']) ?>"></div><div class="product-content"><h3><a href="<?= url('shop-single.php?slug='.rawurlencode($p['slug'])) ?>"><?= h($p['name']) ?></a></h3><p><?= h(money($p['price'])) ?></p><a class="theme-btn" href="<?= url('shop-single.php?slug='.rawurlencode($p['slug'])) ?>">View product</a><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="wishlist"><input type="hidden" name="product_id" value="<?= $p['id'] ?>"><button name="remove" class="btn">Remove</button></form></div></div></div><?php endforeach; if(!$list): ?><p>Your wishlist is empty. <a href="<?= url('shop.php') ?>">Browse products</a>.</p><?php endif; ?></div></div></div>
<?php elseif($view==='cart'): $items=cart_items();$t=totals($items); ?>
<div class="shop-cart py-90"><div class="container"><?php if(!$items): ?><p>Your cart is empty.</p><a class="theme-btn mt-3" href="<?= url('shop.php') ?>">Continue shopping</a><?php else: ?><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="cart_update"><div class="table-responsive"><table class="table store-order-table"><thead><tr><th>Product</th><th>Price</th><th>Quantity</th><th>Total</th></tr></thead><tbody><?php foreach($items as $i): ?><tr><td><a href="<?= url('shop-single.php?slug='.rawurlencode($i['slug'])) ?>"><img width="70" height="70" style="object-fit:contain" src="<?= h(url($i['image']?:'assets/img/logo/favicon.png')) ?>" alt=""> <?= h($i['name']) ?></a><?php if($i['options']): ?><small><?= h(implode(' / ',json_decode($i['options'],true)?:[])) ?></small><?php endif; ?></td><td><?= h(money($i['price'])) ?></td><td><input aria-label="Quantity for <?= h($i['name']) ?>" type="number" name="quantity[<?= $i['id'] ?>]" value="<?= $i['quantity'] ?>" min="0" max="99" class="form-control" style="width:85px"><small>Set 0 to remove</small></td><td><?= h(money($i['price']*$i['quantity'])) ?></td></tr><?php endforeach; ?></tbody></table></div><button class="theme-btn">Update cart</button></form><div class="row mt-4"><div class="col-lg-5 ms-auto"><div class="shop-cart-summary"><h4>Cart totals</h4><ul><?php foreach($t as $k=>$v): ?><li><?= h(ucfirst($k)) ?><span><?= h(money($v)) ?></span></li><?php endforeach; ?></ul><a class="theme-btn mt-3" href="<?= url('shop-checkout.php') ?>">Proceed to checkout<i class="far fa-arrow-right"></i></a></div></div></div><?php endif; ?></div></div>
<?php elseif($view==='checkout'): $items=cart_items();$t=totals($items);$u=user();$address=$u?row('SELECT * FROM addresses WHERE user_id=? ORDER BY id DESC LIMIT 1',[$u['id']]):null;if(empty($_SESSION['checkout_key'])||scalar('SELECT id FROM orders WHERE checkout_key=?',[$_SESSION['checkout_key']]))$_SESSION['checkout_key']=bin2hex(random_bytes(32)); ?>
<div class="shop-checkout py-90"><div class="container"><?php if(!$items): ?><p>Your cart is empty. <a href="<?= url('shop.php') ?>">Continue shopping</a>.</p><?php else: ?><form method="post" class="store-form"><?= csrf_field() ?><input type="hidden" name="action" value="checkout"><input type="hidden" name="checkout_key" value="<?= h($_SESSION['checkout_key']) ?>"><div class="row"><div class="col-lg-7"><h3 class="mb-4">Delivery details</h3><?php foreach(['name'=>'Full name','email'=>'Email','phone'=>'Phone','address'=>'Delivery address','city'=>'City / town','country'=>'Country'] as $k=>$label): ?><label for="<?= $k ?>"><?= $label ?></label><input id="<?= $k ?>" name="<?= $k ?>" type="<?= $k==='email'?'email':'text' ?>" required maxlength="<?= $k==='address'?2000:190 ?>" value="<?= h($_POST[$k]??$address[$k]??$u[$k]??($k==='country'?setting('country','Kenya'):'')) ?>"><?php endforeach; ?><label for="notes">Order notes (optional)</label><textarea id="notes" name="notes" rows="3" maxlength="2000"><?= h($_POST['notes']??'') ?></textarea></div><div class="col-lg-5"><div class="shop-cart-summary"><h3 class="mb-4">Your order</h3><ul><?php foreach($items as $i): ?><li><?= h($i['name']) ?> &times; <?= $i['quantity'] ?><span><?= h(money($i['price']*$i['quantity'])) ?></span></li><?php endforeach; foreach($t as $k=>$v): ?><li><?= ucfirst($k) ?><span><?= h(money($v)) ?></span></li><?php endforeach; ?></ul><label class="mt-4" for="payment_method">Payment method</label><select id="payment_method" name="payment_method" required><option value="">Choose payment method</option><?php foreach(['cod'=>'Payment on delivery','bank_transfer'=>'Bank transfer'] as $k=>$v): if(setting('payment_'.$k,'0')==='1'): ?><option value="<?= $k ?>"><?= $v ?></option><?php endif; endforeach; ?></select><p class="mb-3">Your order is confirmed after review by the store. No card information is collected here.</p><button class="theme-btn">Place order <i class="far fa-arrow-right"></i></button></div></div></div></form><?php endif; ?></div></div>
<?php elseif($view==='order'): $items=rows('SELECT * FROM order_items WHERE order_id=?',[$order['id']]); ?>
<div class="py-90"><div class="container"><div class="user-card"><h3>Order #<?= $order['id'] ?></h3><p><?= h($order['created_at']) ?> · <?= h(ucfirst($order['status'])) ?> · Payment: <?= h($order['payment_status']) ?></p><p class="mt-3"><?= h($order['customer_name']) ?><br><?= nl2br(h($order['address'])) ?><br><?= h($order['city'].' '.$order['country']) ?></p><div class="table-responsive mt-4"><table class="table store-order-table"><thead><tr><th>Product</th><th>Quantity</th><th>Unit price</th><th>Total</th></tr></thead><tbody><?php foreach($items as $i): ?><tr><td><?= h($i['name']) ?></td><td><?= $i['quantity'] ?></td><td><?= h($order['currency'].' '.number_format($i['unit_price'],2)) ?></td><td><?= h($order['currency'].' '.number_format($i['total'],2)) ?></td></tr><?php endforeach; ?></tbody></table></div><?php foreach(['subtotal','shipping','tax','total'] as $k): ?><p><?= ucfirst($k) ?>: <strong><?= h($order['currency'].' '.number_format($order[$k],2)) ?></strong></p><?php endforeach; ?><p class="mt-3">Payment method: <?= h(str_replace('_',' ',$order['payment_method'])) ?></p><?php if($order['payment_method']==='bank_transfer'): ?><p><?= nl2br(h(setting('bank_instructions'))) ?></p><?php endif; ?><h4 class="mt-4">Order updates</h4><?php foreach(rows('SELECT * FROM order_history WHERE order_id=? ORDER BY id',[$order['id']]) as $history): ?><p><?= h($history['created_at'].' — '.ucfirst($history['status'])) ?></p><?php endforeach; ?><button class="theme-btn no-print mt-3" onclick="window.print()">Print order</button></div></div></div>
<?php endif; ?>
